#include <iostream>
#include <vector>

int main() {
    // Create a dynamic array to store integers
    std::vector<int> numbers;  // Empty vector
    numbers.push_back(10);    // Add elements dynamically
    numbers.push_back(20);
    numbers.push_back(30);

    // Iterate and print elements using a range-based for loop
    for (const auto& num : numbers) {
        std::cout << num << " ";  // Output: 10 20 30
    }
    std::cout << std::endl;

    // Check size and access elements
    std::cout << "Vector size: " << numbers.size() << std::endl;  // Output: 3

    return 0;
}
